// Generates docs/rules.md from the rule metadata in dist/. Run via `npm run docs`.
// With --check, fails instead of writing when the file is out of date (used in CI).
import { readFile, writeFile } from "node:fs/promises";
import { providers } from "../dist/index.js";

const target = new URL("../docs/rules.md", import.meta.url);

const lines = [
  "# Rules",
  "",
  "<!-- Generated by scripts/gen-rules-doc.mjs from the rule metadata. Do not edit by hand; run `npm run docs`. -->",
  "",
  "Every rule is derived from the provider's official documentation and records the date it was last checked against it.",
  "",
  "- **error**: the provider documents the construct as unsupported, and the API rejects the schema.",
  "- **warn**: undocumented, ambiguous, or accepted-but-risky. The schema may work, silently lose the constraint, or be rejected.",
  "",
  "Rules marked **fixable** are rewritten automatically by `schemafit --fix --provider <id> <file>`.",
  "",
];

for (const provider of Object.values(providers)) {
  lines.push(`## ${provider.name}`, "", `Models: ${provider.mode}`, "");
  lines.push("| Rule | Severity | Summary |", "| --- | --- | --- |");
  for (const rule of provider.rules) {
    lines.push(`| [\`${rule.id}\`](#${rule.id.replace("/", "")}) | ${rule.severity} | ${rule.summary} |`);
  }
  lines.push("");

  for (const rule of provider.rules) {
    lines.push(`### ${rule.id}`, "", rule.summary, "");
    if (rule.notes) lines.push(`> ${rule.notes}`, "");
    lines.push(`- Severity: **${rule.severity}**`);
    if (rule.fixable) lines.push("- Fixable: **yes**, with `--fix`");
    lines.push(`- Source: <${rule.source}>`, `- Last verified: ${rule.verified}`, "");
  }
}

const content = lines.join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(() => "");
  if (current.replace(/\r\n/g, "\n") !== content) {
    console.error("docs/rules.md is out of date. Run `npm run docs` and commit the result.");
    process.exit(1);
  }
  console.log("docs/rules.md is up to date.");
} else {
  await writeFile(target, content);
  console.log("Wrote docs/rules.md");
}
